package com.local.tyranopocket.core;

import java.io.File;
import java.io.IOException;
import java.util.HashSet;
import java.util.List;

/** Must be invoked on archives actually generated by the pinned @electron/asar tool. */
public final class OfficialAsarChecks {
    public static void main(String[] args) throws Exception {
        File fixtures = new File(args[0]);
        File work = new File(args[1]);
        File source = new File(fixtures, "source");
        List<String> expected = SafeFiles.list(source);
        if (expected.isEmpty()) throw new IOException("Official source fixture missing");
        for (String name : new String[]{"app.asar", "unpacked.asar"}) {
            File archive = new File(fixtures, name);
            File destination = new File(work, name);
            SafeFiles.delete(destination);
            try (AsarReader reader = new AsarReader(archive)) {
                if (name.equals("unpacked.asar")) {
                    boolean found = false;
                    for (AsarReader.Entry entry : reader.entries()) found |= entry.unpacked;
                    if (!found) throw new AssertionError("Official unpacked fixture did not unpack any file");
                }
                reader.extract(destination, new File(fixtures, name + ".unpacked"), SafeFiles.NONE);
            }
            if (!new HashSet<>(expected).equals(new HashSet<>(SafeFiles.list(destination))))
                throw new AssertionError("Official file enumeration mismatch: " + name);
            for (String relative : expected) {
                if (!SafeFiles.hash(SafeFiles.child(source, relative)).equals(
                        SafeFiles.hash(SafeFiles.child(destination, relative))))
                    throw new AssertionError("Official byte mismatch: " + relative);
            }
            System.out.println("PASS official @electron/asar bytes, Unicode, enumeration: " + name);
        }
        System.out.println("RESULT official ASAR interoperability passed; Android runtime NOT tested here");
    }
}
